make everything monochromehtml {
    filter: grayscale(100%) !important;
}

html::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.35);
    pointer-events: none;
    z-index: 999999;
}

